#include "kernel_operator.h"

constexpr int BUFFER_NUM = 2;

struct TilingData {
    int64_t N;
    int64_t C;
    int64_t D_in;
    int64_t H_in;
    int64_t W_in;
    int64_t D_out;
    int64_t H_out;
    int64_t W_out;
    int64_t alignCorners;
    int64_t totalSlices;
    int64_t tasksPerCore;
    int64_t tileSpatial;
};


template <typename T>
class KernelResizeUpsampleTrilinear {
public:
    __aicore__ inline KernelResizeUpsampleTrilinear() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tiling, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tiling);

        // Bind GM tensors
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x));
        yGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y));

        // Calculate input/output sizes
        inputSpatialSize_ = tiling_.D_in * tiling_.H_in * tiling_.W_in;
        outputSpatialSize_ = tiling_.D_out * tiling_.H_out * tiling_.W_out;
        inputSliceSize_ = inputSpatialSize_;
        outputSliceSize_ = outputSpatialSize_;

        // Scale factors
        if (tiling_.alignCorners != 0) {
            scaleD_ = (tiling_.D_out > 1) ? static_cast<float>(tiling_.D_in - 1) / static_cast<float>(tiling_.D_out - 1) : 0.0f;
            scaleH_ = (tiling_.H_out > 1) ? static_cast<float>(tiling_.H_in - 1) / static_cast<float>(tiling_.H_out - 1) : 0.0f;
            scaleW_ = (tiling_.W_out > 1) ? static_cast<float>(tiling_.W_in - 1) / static_cast<float>(tiling_.W_out - 1) : 0.0f;
        } else {
            scaleD_ = static_cast<float>(tiling_.D_in) / static_cast<float>(tiling_.D_out);
            scaleH_ = static_cast<float>(tiling_.H_in) / static_cast<float>(tiling_.H_out);
            scaleW_ = static_cast<float>(tiling_.W_in) / static_cast<float>(tiling_.W_out);
        }

        // Init queues
        pipe->InitBuffer(inQueueX, BUFFER_NUM, tiling_.tileSpatial * sizeof(T));
        pipe->InitBuffer(outQueueY, BUFFER_NUM, tiling_.tileSpatial * sizeof(T));

        // Init temp buffers in UB
        pipe->InitBuffer(tmpBuf1, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf2, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf3, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf4, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf5, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf6, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf7, tiling_.tileSpatial * sizeof(float));
        pipe->InitBuffer(tmpBuf8, tiling_.tileSpatial * sizeof(float));
    }

    __aicore__ inline void Process() {
        int64_t coreIdx = GetBlockIdx();

        for (int64_t localIdx = 0; localIdx < tiling_.tasksPerCore; localIdx++) {
            int64_t sliceIdx = coreIdx * tiling_.tasksPerCore + localIdx;
            if (sliceIdx >= tiling_.totalSlices) {
                break;
            }

            int64_t n = sliceIdx / tiling_.C;
            int64_t c = sliceIdx % tiling_.C;

            int64_t inputBase = n * tiling_.C * inputSliceSize_ + c * inputSliceSize_;
            int64_t outputBase = n * tiling_.C * outputSliceSize_ + c * outputSliceSize_;

            int64_t numTiles = (outputSpatialSize_ + tiling_.tileSpatial - 1) / tiling_.tileSpatial;

            for (int64_t tileId = 0; tileId < numTiles; tileId++) {
                int64_t tileStart = tileId * tiling_.tileSpatial;
                int64_t tileEnd = tileStart + tiling_.tileSpatial;
                if (tileEnd > outputSpatialSize_) {
                    tileEnd = outputSpatialSize_;
                }
                int64_t tileLen = tileEnd - tileStart;

                CopyIn(tileStart, tileLen, inputBase);
                Compute(tileLen, inputBase);
                CopyOut(tileStart, tileLen, outputBase);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t tileStart, int64_t tileLen, int64_t inputBase) {
        // For trilinear interpolation, we need to gather 8 neighbors per output pixel.
        // This is done in Compute using scalar gather, so CopyIn is minimal.
        // We just prepare the input base offset.
        inputBase_ = inputBase;
        tileStart_ = tileStart;
    }

    __aicore__ inline void Compute(int64_t tileLen, int64_t inputBase) {
        // Get temp buffers
        AscendC::LocalTensor<float> v0 = tmpBuf1.Get<float>();
        AscendC::LocalTensor<float> v1 = tmpBuf2.Get<float>();
        AscendC::LocalTensor<float> v2 = tmpBuf3.Get<float>();
        AscendC::LocalTensor<float> v3 = tmpBuf4.Get<float>();
        AscendC::LocalTensor<float> v4 = tmpBuf5.Get<float>();
        AscendC::LocalTensor<float> v5 = tmpBuf6.Get<float>();
        AscendC::LocalTensor<float> v6 = tmpBuf7.Get<float>();
        AscendC::LocalTensor<float> v7 = tmpBuf8.Get<float>();

        AscendC::LocalTensor<float> outLocal = outQueueY.AllocTensor<float>();

        int64_t D_out = tiling_.D_out;
        int64_t H_out = tiling_.H_out;
        int64_t W_out = tiling_.W_out;
        int64_t D_in = tiling_.D_in;
        int64_t H_in = tiling_.H_in;
        int64_t W_in = tiling_.W_in;
        int64_t alignCorners = tiling_.alignCorners;

        // Process each output pixel
        for (int64_t i = 0; i < tileLen; i++) {
            int64_t flatIdx = tileStart_ + i;

            int64_t od = flatIdx / (H_out * W_out);
            int64_t rem = flatIdx % (H_out * W_out);
            int64_t oh = rem / W_out;
            int64_t ow = rem % W_out;

            // Compute input coordinates
            float id_coord, ih_coord, iw_coord;
            if (alignCorners != 0) {
                id_coord = static_cast<float>(od) * scaleD_;
                ih_coord = static_cast<float>(oh) * scaleH_;
                iw_coord = static_cast<float>(ow) * scaleW_;
            } else {
                id_coord = (static_cast<float>(od) + 0.5f) * scaleD_ - 0.5f;
                ih_coord = (static_cast<float>(oh) + 0.5f) * scaleH_ - 0.5f;
                iw_coord = (static_cast<float>(ow) + 0.5f) * scaleW_ - 0.5f;
            }

            // Clamp
            if (id_coord < 0.0f) id_coord = 0.0f;
            if (id_coord > static_cast<float>(D_in - 1)) id_coord = static_cast<float>(D_in - 1);
            if (ih_coord < 0.0f) ih_coord = 0.0f;
            if (ih_coord > static_cast<float>(H_in - 1)) ih_coord = static_cast<float>(H_in - 1);
            if (iw_coord < 0.0f) iw_coord = 0.0f;
            if (iw_coord > static_cast<float>(W_in - 1)) iw_coord = static_cast<float>(W_in - 1);

            // Floor indices
            int64_t id0 = static_cast<int64_t>(id_coord);
            int64_t ih0 = static_cast<int64_t>(ih_coord);
            int64_t iw0 = static_cast<int64_t>(iw_coord);

            // Ceil indices (clamped)
            int64_t id1 = (id0 + 1 < D_in) ? (id0 + 1) : (D_in - 1);
            int64_t ih1 = (ih0 + 1 < H_in) ? (ih0 + 1) : (H_in - 1);
            int64_t iw1 = (iw0 + 1 < W_in) ? (iw0 + 1) : (W_in - 1);

            // Fractional parts
            float wd = id_coord - static_cast<float>(id0);
            float wh = ih_coord - static_cast<float>(ih0);
            float ww = iw_coord - static_cast<float>(iw0);
            float wd1 = 1.0f - wd;
            float wh1 = 1.0f - wh;
            float ww1 = 1.0f - ww;

            // Gather 8 neighboring values from GM
            float val0, val1, val2, val3, val4, val5, val6, val7;

            val0 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw0));
            val1 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw1));
            val2 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw0));
            val3 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw1));
            val4 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih0 * W_in + iw0));
            val5 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih0 * W_in + iw1));
            val6 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih1 * W_in + iw0));
            val7 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih1 * W_in + iw1));

            // Trilinear interpolation
            float result = wd1 * wh1 * ww1 * val0
                         + wd1 * wh1 * ww  * val1
                         + wd1 * wh  * ww1 * val2
                         + wd1 * wh  * ww  * val3
                         + wd  * wh1 * ww1 * val4
                         + wd  * wh1 * ww  * val5
                         + wd  * wh  * ww1 * val6
                         + wd  * wh  * ww  * val7;

            // Store result
            outLocal.SetValue(i, result);
        }

        outQueueY.EnQue<float>(outLocal);
    }

    __aicore__ inline void CopyOut(int64_t tileStart, int64_t tileLen, int64_t outputBase) {
        AscendC::LocalTensor<float> outLocal = outQueueY.DeQue<float>();

        // Cast and write back to GM
        for (int64_t i = 0; i < tileLen; i++) {
            int64_t flatIdx = tileStart + i;
            float val = outLocal.GetValue(i);

            if constexpr (std::is_same_v<T, float>) {
                yGm.SetValue(outputBase + flatIdx, val);
            } else {
                yGm.SetValue(outputBase + flatIdx, static_cast<T>(val));
            }
        }

        outQueueY.FreeTensor(outLocal);
    }

private:
    TilingData tiling_;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;

    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf5;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf6;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf7;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf8;

    int64_t inputSpatialSize_;
    int64_t outputSpatialSize_;
    int64_t inputSliceSize_;
    int64_t outputSliceSize_;
    float scaleD_;
    float scaleH_;
    float scaleW_;
    int64_t inputBase_;
    int64_t tileStart_;
};


extern "C" __global__ __aicore__ void resize_upsample_trilinear(GM_ADDR x, GM_ADDR y, GM_ADDR tiling) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    AscendC::TPipe pipe;

    // Determine dtype from tiling and dispatch
    TilingData td;
    CopyTiling(&td, tiling);

    // We use float kernel for all dtypes (cast inside)
    KernelResizeUpsampleTrilinear<float> kernel;
    kernel.Init(x, y, tiling, &pipe);
    kernel.Process();
}
