#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_resize_upsample_trilinear.h"

namespace ascend_kernel {

struct TilingData {
    int64_t N;
    int64_t C;
    int64_t D_in;
    int64_t H_in;
    int64_t W_in;
    int64_t D_out;
    int64_t H_out;
    int64_t W_out;
    int64_t alignCorners;
    int64_t totalSlices;
    int64_t tasksPerCore;
    int64_t tileSpatial;
};

at::Tensor resize_upsample_trilinear(
    const at::Tensor& x,
    at::IntArrayRef output_size,
    bool align_corners
) {
    // Input validation
    TORCH_CHECK(x.dim() == 5, "resize_upsample_trilinear: input must be 5D (N,C,D,H,W)");
    TORCH_CHECK(output_size.size() == 3, "resize_upsample_trilinear: output_size must have 3 elements (D,H,W)");

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t D_in = x.size(2);
    int64_t H_in = x.size(3);
    int64_t W_in = x.size(4);
    int64_t D_out = output_size[0];
    int64_t H_out = output_size[1];
    int64_t W_out = output_size[2];

    // Create output tensor
    auto y = at::empty({N, C, D_out, H_out, W_out}, x.options());

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling: each core handles (N*C) slices
    int64_t totalSlices = N * C;
    int64_t usedCoreNum = std::min(coreNum, totalSlices);
    int64_t tasksPerCore = (totalSlices + usedCoreNum - 1) / usedCoreNum;

    // UB-level tiling: tile size for spatial processing
    // Each output pixel needs ~8 float temps + 1 output = ~36 bytes
    // Leave some room for overhead, use conservative tile size
    int64_t tileSpatial = 64;
    int64_t bytesPerPixel = 36;  // approx
    int64_t maxTileByUB = static_cast<int64_t>(ubSize) / bytesPerPixel;
    if (maxTileByUB < tileSpatial) {
        tileSpatial = maxTileByUB;
    }
    if (tileSpatial < 1) {
        tileSpatial = 1;
    }

    // Build tiling data
    TilingData tiling;
    tiling.N = N;
    tiling.C = C;
    tiling.D_in = D_in;
    tiling.H_in = H_in;
    tiling.W_in = W_in;
    tiling.D_out = D_out;
    tiling.H_out = H_out;
    tiling.W_out = W_out;
    tiling.alignCorners = align_corners ? 1 : 0;
    tiling.totalSlices = totalSlices;
    tiling.tasksPerCore = tasksPerCore;
    tiling.tileSpatial = tileSpatial;

    // Convert tiling to tensor for kernel
    auto tilingTensor = at::from_blob(
        &tiling,
        {static_cast<int64_t>(sizeof(TilingData) / sizeof(int64_t))},
        at::TensorOptions().dtype(at::kLong).device(at::kCPU)
    ).clone();

    // Ensure all args are left values
    int64_t blockDim = usedCoreNum;
    int64_t alignCornersVal = align_corners ? 1 : 0;

    // Launch kernel
    EXEC_KERNEL_CMD(
        resize_upsample_trilinear,
        blockDim,
        x,
        y,
        tilingTensor
    );

    return y;
}

} // namespace ascend_kernel
