80	            if (sliceIdx >= tiling_.totalSlices) {
81	                break;
82	            }
83	
84	            int64_t n = sliceIdx / tiling_.C;
85	            int64_t c = sliceIdx % tiling_.C;
86	
87	            int64_t inputBase = n * tiling_.C * inputSliceSize_ + c * inputSliceSize_;
88	            int64_t outputBase = n * tiling_.C * outputSliceSize_ + c * outputSliceSize_;
89	
90	            int64_t numTiles = (outputSpatialSize_ + tiling_.tileSpatial - 1) / tiling_.tileSpatial;
91	
92	            for (int64_t tileId = 0; tileId < numTiles; tileId++) {
93	                int64_t tileStart = tileId * tiling_.tileSpatial;
94	                int64_t tileEnd = tileStart + tiling_.tileSpatial;
95	                if (tileEnd > outputSpatialSize_) {
96	                    tileEnd = outputSpatialSize_;
97	                }
98	                int64_t tileLen = tileEnd - tileStart;
99	
100	                CopyIn(tileStart, tileLen, inputBase);
101	                Compute(tileLen, inputBase);
102	                CopyOut(tileStart, tileLen, outputBase);
103	            }
104	        }
105	    }
