107	private:
108	    __aicore__ inline void CopyIn(int64_t tileStart, int64_t tileLen, int64_t inputBase) {
109	        // For trilinear interpolation, we need to gather 8 neighbors per output pixel.
110	        // This is done in Compute using scalar gather, so CopyIn is minimal.
111	        // We just prepare the input base offset.
112	        inputBase_ = inputBase;
113	        tileStart_ = tileStart;
114	    }
115	
116	    __aicore__ inline void Compute(int64_t tileLen, int64_t inputBase) {
117	        // Get temp buffers
118	        AscendC::LocalTensor<float> v0 = tmpBuf1.Get<float>();
119	        AscendC::LocalTensor<float> v1 = tmpBuf2.Get<float>();
120	        AscendC::LocalTensor<float> v2 = tmpBuf3.Get<float>();
121	        AscendC::LocalTensor<float> v3 = tmpBuf4.Get<float>();
122	        AscendC::LocalTensor<float> v4 = tmpBuf5.Get<float>();
123	        AscendC::LocalTensor<float> v5 = tmpBuf6.Get<float>();
124	        AscendC::LocalTensor<float> v6 = tmpBuf7.Get<float>();
125	        AscendC::LocalTensor<float> v7 = tmpBuf8.Get<float>();
126	
127	        AscendC::LocalTensor<float> outLocal = outQueueY.AllocTensor<float>();
128	
129	        int64_t D_out = tiling_.D_out;
130	        int64_t H_out = tiling_.H_out;
131	        int64_t W_out = tiling_.W_out;
132	        int64_t D_in = tiling_.D_in;
133	        int64_t H_in = tiling_.H_in;
134	        int64_t W_in = tiling_.W_in;
135	        int64_t alignCorners = tiling_.alignCorners;
136	
137	        // Process each output pixel
138	        for (int64_t i = 0; i < tileLen; i++) {
139	            int64_t flatIdx = tileStart_ + i;
140	
141	            int64_t od = flatIdx / (H_out * W_out);
142	            int64_t rem = flatIdx % (H_out * W_out);
143	            int64_t oh = rem / W_out;
144	            int64_t ow = rem % W_out;
145	
146	            // Compute input coordinates
147	            float id_coord, ih_coord, iw_coord;
148	            if (alignCorners != 0) {
149	                id_coord = static_cast<float>(od) * scaleD_;
150	                ih_coord = static_cast<float>(oh) * scaleH_;
151	                iw_coord = static_cast<float>(ow) * scaleW_;
152	            } else {
153	                id_coord = (static_cast<float>(od) + 0.5f) * scaleD_ - 0.5f;
154	                ih_coord = (static_cast<float>(oh) + 0.5f) * scaleH_ - 0.5f;
155	                iw_coord = (static_cast<float>(ow) + 0.5f) * scaleW_ - 0.5f;
156	            }
157	
158	            // Clamp
159	            if (id_coord < 0.0f) id_coord = 0.0f;
160	            if (id_coord > static_cast<float>(D_in - 1)) id_coord = static_cast<float>(D_in - 1);
161	            if (ih_coord < 0.0f) ih_coord = 0.0f;
162	            if (ih_coord > static_cast<float>(H_in - 1)) ih_coord = static_cast<float>(H_in - 1);
163	            if (iw_coord < 0.0f) iw_coord = 0.0f;
164	            if (iw_coord > static_cast<float>(W_in - 1)) iw_coord = static_cast<float>(W_in - 1);
165	
166	            // Floor indices
167	            int64_t id0 = static_cast<int64_t>(id_coord);
168	            int64_t ih0 = static_cast<int64_t>(ih_coord);
169	            int64_t iw0 = static_cast<int64_t>(iw_coord);
170	
171	            // Ceil indices (clamped)
172	            int64_t id1 = (id0 + 1 < D_in) ? (id0 + 1) : (D_in - 1);
173	            int64_t ih1 = (ih0 + 1 < H_in) ? (ih0 + 1) : (H_in - 1);
174	            int64_t iw1 = (iw0 + 1 < W_in) ? (iw0 + 1) : (W_in - 1);
175	
176	            // Fractional parts
