178	            float wh = ih_coord - static_cast<float>(ih0);
179	            float ww = iw_coord - static_cast<float>(iw0);
180	            float wd1 = 1.0f - wd;
181	            float wh1 = 1.0f - wh;
182	            float ww1 = 1.0f - ww;
183	
184	            // Gather 8 neighboring values from GM
185	            float val0, val1, val2, val3, val4, val5, val6, val7;
186	
187	            val0 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw0));
