189	            val2 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw0));
190	            val3 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw1));
191	            val4 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih0 * W_in + iw0));
192	            val5 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih0 * W_in + iw1));
193	            val6 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih1 * W_in + iw0));
194	            val7 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih1 * W_in + iw1));
195	
196	            // Trilinear interpolation
197	            float result = wd1 * wh1 * ww1 * val0
198	                         + wd1 * wh1 * ww  * val1
199	                         + wd1 * wh  * ww1 * val2
200	                         + wd1 * wh  * ww  * val3
201	                         + wd  * wh1 * ww1 * val4
202	                         + wd  * wh1 * ww  * val5
203	                         + wd  * wh  * ww1 * val6
204	                         + wd  * wh  * ww  * val7;
205	
206	            // Store result
207	            outLocal.SetValue(i, result);
208	        }
209	
210	        outQueueY.EnQue<float>(outLocal);
211	    }
