213	    __aicore__ inline void CopyOut(int64_t tileStart, int64_t tileLen, int64_t outputBase) {
214	        AscendC::LocalTensor<float> outLocal = outQueueY.DeQue<float>();
215	
216	        // Cast and write back to GM
217	        for (int64_t i = 0; i < tileLen; i++) {
218	            int64_t flatIdx = tileStart + i;
219	            float val = outLocal.GetValue(i);
220	
221	            if constexpr (std::is_same_v<T, float>) {
222	                yGm.SetValue(outputBase + flatIdx, val);
223	            } else {
224	                yGm.SetValue(outputBase + flatIdx, static_cast<T>(val));
225	            }
226	        }
227	
228	        outQueueY.FreeTensor(outLocal);
229	    }
