32	at::Tensor resize_upsample_trilinear(
33	    const at::Tensor& x,
34	    at::IntArrayRef output_size,
35	    bool align_corners
36	) {
37	    // Input validation
38	    TORCH_CHECK(x.dim() == 5, "resize_upsample_trilinear: input must be 5D (N,C,D,H,W)");
39	    TORCH_CHECK(output_size.size() == 3, "resize_upsample_trilinear: output_size must have 3 elements (D,H,W)");
40	
41	    int64_t N = x.size(0);
42	    int64_t C = x.size(1);
43	    int64_t D_in = x.size(2);
44	    int64_t H_in = x.size(3);
45	    int64_t W_in = x.size(4);
46	    int64_t D_out = output_size[0];
47	    int64_t H_out = output_size[1];
48	    int64_t W_out = output_size[2];
49	
50	    // Create output tensor
51	    auto y = at::empty({N, C, D_out, H_out, W_out}, x.options());
52	
53	    // Get platform info
54	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
55	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
56	    uint64_t ubSize;
57	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
58	
59	    // Block-level tiling: each core handles (N*C) slices
60	    int64_t totalSlices = N * C;
61	    int64_t usedCoreNum = std::min(coreNum, totalSlices);
62	    int64_t tasksPerCore = (totalSlices + usedCoreNum - 1) / usedCoreNum;
63	
64	    // UB-level tiling: tile size for spatial processing
65	    // Each output pixel needs ~8 float temps + 1 output = ~36 bytes
66	    // Leave some room for overhead, use conservative tile size
67	    int64_t tileSpatial = 64;
68	    int64_t bytesPerPixel = 36;  // approx
69	    int64_t maxTileByUB = static_cast<int64_t>(ubSize) / bytesPerPixel;
70	    if (maxTileByUB < tileSpatial) {
71	        tileSpatial = maxTileByUB;
72	    }
73	    if (tileSpatial < 1) {
74	        tileSpatial = 1;
75	    }
76	
77	    // Build tiling data
78	    TilingData tiling;
79	    tiling.N = N;
80	    tiling.C = C;
81	    tiling.D_in = D_in;
82	    tiling.H_in = H_in;
83	    tiling.W_in = W_in;
84	    tiling.D_out = D_out;
85	    tiling.H_out = H_out;
86	    tiling.W_out = W_out;
87	    tiling.alignCorners = align_corners ? 1 : 0;
88	    tiling.totalSlices = totalSlices;
89	    tiling.tasksPerCore = tasksPerCore;
90	    tiling.tileSpatial = tileSpatial;
91	
92	    // Convert tiling to tensor for kernel
93	    auto tilingTensor = at::from_blob(
94	        &tiling,
95	        {static_cast<int64_t>(sizeof(TilingData) / sizeof(int64_t))},
96	        at::TensorOptions().dtype(at::kLong).device(at::kCPU)
97	    ).clone();
98	
99	    // Ensure all args are left values
100	    int64_t blockDim = usedCoreNum;
101	    int64_t alignCornersVal = align_corners ? 1 : 0;
102	
103	    // Launch kernel
104	    EXEC_KERNEL_CMD(
105	        resize_upsample_trilinear,
106	        blockDim,
107	        x,
108	        y,
109	        tilingTensor
110	    );
111	
112	    return y;
113	}
