            float wd = id_coord - static_cast<float>(id0);
            float wh = ih_coord - static_cast<float>(ih0);
            float ww = iw_coord - static_cast<float>(iw0);
            float wd1 = 1.0f - wd;
            float wh1 = 1.0f - wh;
            float ww1 = 1.0f - ww;

            // Gather 8 neighboring values from GM
            float val0, val1, val2, val3, val4, val5, val6, val7;

            val0 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw0));
            val1 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw1));
            val2 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw0));
            val3 = static_cast<float>(xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw1));
            val4 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih0 * W_in + iw0));
            val5 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih0 * W_in + iw1));
            val6 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih1 * W_in + iw0));
            val7 = static_cast<float>(xGm.GetValue(inputBase + id1 * H_in * W_in + ih1 * W_in + iw1));

