    TORCH_CHECK(x.dim() == 5, "resize_upsample_trilinear: input must be 5D (N,C,D,H,W)");
    TORCH_CHECK(output_size.size() == 3, "resize_upsample_trilinear: output_size must have 3 elements (D,H,W)");

