class KernelResizeUpsampleTrilinear {
public:
    __aicore__ inline KernelResizeUpsampleTrilinear() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tiling, AscendC::TPipe *pipe) {
        CopyTilingData(&tiling_, tiling, sizeof(TilingData));

        // Bind GM tensors (always float32)
        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x));
        yGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y));

        // Calculate input/output sizes
        inputSpatialSize_ = tiling_.D_in * tiling_.H_in * tiling_.W_in;
        outputSpatialSize_ = tiling_.D_out * tiling_.H_out * tiling_.W_out;
        inputSliceSize_ = inputSpatialSize_;
        outputSliceSize_ = outputSpatialSize_;

        // Scale factors
        if (tiling_.alignCorners != 0) {
            scaleD_ = (tiling_.D_out > 1) ? static_cast<float>(tiling_.D_in - 1) / static_cast<float>(tiling_.D_out - 1) : 0.0f;
            scaleH_ = (tiling_.H_out > 1) ? static_cast<float>(tiling_.H_in - 1) / static_cast<float>(tiling_.H_out - 1) : 0.0f;
            scaleW_ = (tiling_.W_out > 1) ? static_cast<float>(tiling_.W_in - 1) / static_cast<float>(tiling_.W_out - 1) : 0.0f;
        } else {
            scaleD_ = static_cast<float>(tiling_.D_in) / static_cast<float>(tiling_.D_out);
            scaleH_ = static_cast<float>(tiling_.H_in) / static_cast<float>(tiling_.H_out);
            scaleW_ = static_cast<float>(tiling_.W_in) / static_cast<float>(tiling_.W_out);
        }
    }

    __aicore__ inline void Process() {
        int64_t coreIdx = AscendC::GetBlockIdx();

        for (int64_t localIdx = 0; localIdx < tiling_.tasksPerCore; localIdx++) {
            int64_t sliceIdx = coreIdx * tiling_.tasksPerCore + localIdx;
            if (sliceIdx >= tiling_.totalSlices) {
                break;
            }

            int64_t n = sliceIdx / tiling_.C;
            int64_t c = sliceIdx % tiling_.C;

            int64_t inputBase = n * tiling_.C * inputSliceSize_ + c * inputSliceSize_;
            int64_t outputBase = n * tiling_.C * outputSliceSize_ + c * outputSliceSize_;

            // Process all output pixels for this slice directly without tiling
            ComputeAll(inputBase, outputBase);
        }
    }

private:
    __aicore__ inline void ComputeAll(int64_t inputBase, int64_t outputBase) {
        int64_t D_out = tiling_.D_out;
        int64_t H_out = tiling_.H_out;
        int64_t W_out = tiling_.W_out;
        int64_t D_in = tiling_.D_in;
        int64_t H_in = tiling_.H_in;
        int64_t W_in = tiling_.W_in;
        int64_t alignCorners = tiling_.alignCorners;

        int64_t totalOut = outputSpatialSize_;

        // Process each output pixel
        for (int64_t flatIdx = 0; flatIdx < totalOut; flatIdx++) {
            int64_t od = flatIdx / (H_out * W_out);
            int64_t rem = flatIdx % (H_out * W_out);
            int64_t oh = rem / W_out;
            int64_t ow = rem % W_out;

