            int64_t ih1 = (ih0 + 1 < H_in) ? (ih0 + 1) : (H_in - 1);
            int64_t iw1 = (iw0 + 1 < W_in) ? (iw0 + 1) : (W_in - 1);

            // Fractional parts
            float wd = id_coord - static_cast<float>(id0);
            float wh = ih_coord - static_cast<float>(ih0);
            float ww = iw_coord - static_cast<float>(iw0);
            float wd1 = 1.0f - wd;
            float wh1 = 1.0f - wh;
            float ww1 = 1.0f - ww;

            // Gather 8 neighboring values from GM
            float val0 = xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw0);
            float val1 = xGm.GetValue(inputBase + id0 * H_in * W_in + ih0 * W_in + iw1);
            float val2 = xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw0);
            float val3 = xGm.GetValue(inputBase + id0 * H_in * W_in + ih1 * W_in + iw1);
